CREATE TABLE "cell_monthly_metrics" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "period" date NOT NULL, "ais_hours" bigint NOT NULL CHECK ("ais_hours" >= 0), "ais_vessel_ids_sum" bigint NOT NULL CHECK ("ais_vessel_ids_sum" >= 0), "ais_observation_count" integer NOT NULL CHECK ("ais_observation_count" >= 0), "ais_flag_count" smallint NOT NULL CHECK ("ais_flag_count" >= 0), "sar_matched_detections" bigint NOT NULL CHECK ("sar_matched_detections" >= 0), "sar_matched_vessel_ids_sum" bigint NOT NULL CHECK ("sar_matched_vessel_ids_sum" >= 0), "sar_matched_observation_count" integer NOT NULL CHECK ("sar_matched_observation_count" >= 0), "sar_unmatched_detections" bigint NOT NULL CHECK ("sar_unmatched_detections" >= 0), "sar_unmatched_vessel_ids_sum" bigint NOT NULL CHECK ("sar_unmatched_vessel_ids_sum" >= 0), "sar_unmatched_observation_count" integer NOT NULL CHECK ("sar_unmatched_observation_count" >= 0), "generated_at" timestamp with time zone NOT NULL, "zone_intersection_id" bigint NOT NULL, CONSTRAINT "unique_cell_zone_monthly_metric" UNIQUE ("zone_intersection_id", "period"));
